<div class="page-head"><div><span class="eyebrow dark"><?= e(tr('ردپای ممیزی','Audit trail')) ?></span><h1><?= e(tr('گزارش فعالیت','Activity log')) ?></h1><p><?= e(tr('۲۵۰ رویداد اخیر مدیران و عملیات خودکار', 'Latest 250 administrator and automated events')) ?></p></div></div>
<section class="panel"><div class="table-wrap"><table><thead><tr><th><?= e(tr('زمان','Time')) ?></th><th><?= e(tr('مدیر','Administrator')) ?></th><th><?= e(tr('عملیات','Action')) ?></th><th><?= e(tr('هدف','Target')) ?></th><th><?= e(tr('جزئیات','Details')) ?></th><th>IP</th></tr></thead><tbody><?php foreach($logs as $log):?><tr><td><?= e($log['created_at']) ?></td><td><?= e($log['admin_name']?:tr('سیستم','System')) ?></td><td><strong><?= e($log['action']) ?></strong></td><td><?= e($log['target_type']) ?><?= $log['target_id']?' #'.e($log['target_id']):'' ?></td><td><code class="detail-code"><?= e($log['detail']?:'{}') ?></code></td><td dir="ltr"><?= e($log['ip_address']) ?></td></tr><?php endforeach;?><?php if(!$logs):?><tr><td colspan="6" class="empty"><?= e(tr('رویدادی ثبت نشده است.','No events recorded.')) ?></td></tr><?php endif;?></tbody></table></div></section>

